#include <Arduino.h>

void setup() {
  pinMode(8, OUTPUT);
  pinMode(9, INPUT);
  pinMode(13, OUTPUT);
  pinMode(6, OUTPUT);
  digitalWrite(8, LOW);
  digitalWrite(13, LOW);
  noTone(6);
}

void loop() {
  digitalWrite(8, LOW);
  delayMicroseconds(2);
  digitalWrite(8, HIGH);
  delayMicroseconds(10);
  digitalWrite(8, LOW);
  unsigned long duration = pulseIn(9, HIGH, 30000UL);
  float distanceCm = duration / 58.0f;
  bool alarm = duration != 0 && distanceCm < 20.0f;
  digitalWrite(13, alarm ? HIGH : LOW);
  if (alarm) {
    tone(6, 1000);
  } else {
    noTone(6);
    digitalWrite(6, LOW);
  }
  delay(60);
}
